SELECT percentile_cont(0.75) within GROUP (ORDER BY AVG(hr)) AS percentile_75 FROM (SELECT AVG(hr) AS avg_hr FROM (SELECT h.hadm_id, h.stay_id, h.charttime, h.value, h.valuenum, h.valueuom, h.itemid, h.seq_num, h.poe_id, h.poe_seq, h.orderid, h.linkorderid, h.ordercategoryname, h.ordercategorydescription, h.patientweight, h.isopenbag, h.statusdescription, h.originalamount, h.originalrate FROM chartevents h JOIN icustays i ON h.hadm_id = i.hadm_id AND h.stay_id = i.stay_id WHERE h.itemid = 85 AND h.valueuom = 'bpm' AND h.value = 110 AND h.charttime BETWEEN i.intime AND i.intime + interval '24 hours' AND h.charttime <= i.outtime AND i.subject_id IN (SELECT subject_id FROM patients WHERE gender = 'F' AND age(CURRENT_DATE, dob) BETWEEN 67 AND 77) GROUP BY h.hadm_id, h.stay_id, h.charttime) AS subquery;